function longestCommonPrefix(strs: string[]): string {
  const first = strs[0];

  // Вертикальное сканирование: проверяем i-й символ сразу во всех строках
  for (let i = 0; i < first.length; i++) {
    const ch = first[i];

    for (let j = 1; j < strs.length; j++) {
      // Строка закончилась или символ не совпал — префикс найден
      if (i >= strs[j].length || strs[j][i] !== ch) {
        return first.slice(0, i);
      }
    }
  }

  // Первая строка целиком является префиксом всех остальных
  return first;
}

// Время: O(S), где S — суммарная длина строк (в худшем случае)
// Память: O(1) кроме строки-ответа
